import { FC, HTMLAttributes } from 'react';

import { Flex, Typography } from 'antd';
import cn from 'classnames';

import { type BrandRead } from 'entities/Brand';
import { ADVCAMPAIGN_CATEGORIES } from 'shared/consts';

import styles from './BrandHeader.module.scss';

interface IBrandHeaderProps extends HTMLAttributes<HTMLDivElement> {
	brand: BrandRead;
	isShortView?: boolean;
}

export const BrandHeader: FC<IBrandHeaderProps> = ({ className, brand, isShortView, ...props }) => {
	const { categories, image, name } = brand;
	const categoriesString = categories
		.map((category) => ADVCAMPAIGN_CATEGORIES[category.slug] || category.slug)
		.join(', ');

	return (
		<>
			<Flex gap={8} {...props} className={cn(className, styles.brandHeader)}>
				<img className={styles.brandHeader__img} src={image} alt={name} width={100} height={60} />
				<div className={styles.brandHeader__textContent}>
					<Typography.Title level={5} ellipsis={isShortView} className={styles.brandHeader__text}>
						{name}
					</Typography.Title>
					<Typography.Paragraph
						ellipsis={{ rows: 2, tooltip: categoriesString }}
						type="secondary"
						className={cn(styles.brandHeader__text, styles.brandHeader__lineClamp)}>
						{categoriesString}
					</Typography.Paragraph>
				</div>
			</Flex>
		</>
	);
};
